// ⏳ Aynı anda: seçili yılın dönemine ait kısa, şaşırtıcı bilgiler (js/ayni-anda.js gösterir).
// d: [başlangıç, bitiş] bilginin ait olduğu dönem (MÖ pozitif, MS negatif), k: kısa kanca, t: bilgi,
// w: doğrulamak için İngilizce Vikipedi başlığı (kartta "🔎 Kaynak" bağlantısı olur).
// Kural: yalnızca kaynaklarda yerleşik bilgiler; tartışmalı olanlar metinde "sanılıyor / anlatılır" diye belirtilir.
window.AYNI_ANDA = [
  // ---------- Tarih öncesi ----------
  { d: [9600, 8000], k: 'Göbekli Tepe, Stonehenge\'den 6.000 yaş büyük', t: 'Göbekli Tepe\'nin dev dikilitaşları yaklaşık MÖ 9500\'de dikildi: Stonehenge\'den 6.000 yıl, yazının icadından 6.000 yıl önce. Henüz çömlek, tekerlek ve tarım bile yoktu.', w: 'Göbekli Tepe' },
  { d: [8300, 7000], k: 'Eriha Kulesi piramitlerden 5.000 yaş büyük', t: 'Eriha\'daki taş kule yaklaşık MÖ 8000\'de yapıldı. Büyük Piramit\'ten 5.000 yıldan fazla eskidir; bilinen en eski anıtsal yapılardan biridir.', w: 'Tower of Jericho' },
  { d: [9000, 6200], k: 'Britanya henüz bir ada değildi', t: 'Bu çağda Britanya ile Avrupa arasında Doggerland adlı geniş bir kara vardı. Buzullar eridikçe deniz yükseldi ve bu topraklar yaklaşık MÖ 6500–6200 arasında sular altında kaldı.', w: 'Doggerland' },
  { d: [9000, 3500], k: 'Sahra yemyeşildi', t: 'Bu binyıllarda Sahra çöl değil, göller ve otlaklarla kaplıydı. Mısır\'ın Gilf Kebir bölgesindeki kaya resimlerinde yüzen insanlar bile çizilmiştir.', w: 'African humid period' },
  { d: [7100, 5700], k: 'Çatalhöyük\'te evlere çatıdan girilirdi', t: 'Çatalhöyük\'te sokak yoktu: evler bitişik yapılmıştı, insanlar çatıların üstünde yürür ve evlerine çatıdaki delikten merdivenle inerdi.', w: 'Çatalhöyük' },
  { d: [3400, 3100], k: 'Buzlar içindeki Ötzi\'nin 61 dövmesi var', t: 'Alplerde buzulda donmuş bulunan Ötzi bu yıllarda öldü. Vücudunda 61 dövme var; son yemeğinde dağ keçisi eti yemişti.', w: 'Ötzi' },
  { d: [3400, 2900], k: 'İlk yazılar şiir değil, hesap pusulası', t: 'Sümer\'de bulunan en eski çivi yazılı tabletlerin çoğu edebiyat değil; tahıl, bira, koyun ve işçi hesaplarıdır. Yazı önce muhasebe için icat edildi.', w: 'Proto-cuneiform' },
  // ---------- Erken Tunç Çağı ----------
  { d: [2700, 2000], k: 'Piramitler yapılırken mamutlar hâlâ yaşıyordu', t: 'Büyük Piramit MÖ 2560 civarında bitti. Bu sırada Sibirya açıklarındaki Wrangel Adası\'nda son yünlü mamutlar hâlâ yaşıyordu; yaklaşık MÖ 2000\'e kadar soyları sürdü.', w: 'Wrangel Island' },
  { d: [2600, 2450], k: 'Büyük Piramit ile Stonehenge aynı çağda', t: 'Mısır\'da Büyük Piramit yükselirken Britanya\'da Stonehenge\'in büyük sarsen taşları dikiliyordu. İki anıt aşağı yukarı aynı yüzyıla aittir.', w: 'Stonehenge' },
  { d: [2600, 2400], k: 'Piramit işçilerine ekmek ve bira', t: 'Gize\'deki işçiler köle değildi: işçi köylerinde yaşıyor, tayın olarak ekmek ve bira alıyorlardı. Bira o çağda günlük besinin bir parçasıydı.', w: 'Giza pyramid complex' },
  { d: [2600, 1900], k: 'Mohenjo-daro\'da kapalı kanalizasyon vardı', t: 'İndus Vadisi\'nin büyük kenti Mohenjo-daro\'da sokak altından geçen kapalı atık su kanalları ve evlerde banyolar vardı.', w: 'Mohenjo-daro' },
  { d: [2600, 1900], k: 'İndus yazısı hâlâ okunamıyor', t: 'İndus uygarlığının mühürlerindeki yazı bugüne kadar çözülemedi. Bu büyük uygarlığın dilini hâlâ bilmiyoruz.', w: 'Indus script' },
  { d: [2334, 2154], k: 'Dünyanın ilk imparatorluğu kuruluyor', t: 'Akadlı Sargon, Mezopotamya\'nın şehir devletlerini tek yönetim altında birleştirdi. Akad, çoğu tarihçiye göre bilinen ilk imparatorluktur.', w: 'Akkadian Empire' },
  { d: [2300, 2250], k: 'Adı bilinen ilk yazar bir kadın', t: 'Sargon\'un kızı Enheduanna, Ur\'da başrahibeydi. Yazdığı ilahiler sayesinde adı bilinen ilk yazar olarak kabul edilir.', w: 'Enheduanna' },
  { d: [2100, 2050], k: 'Bilinen en eski yasa: Ur-Nammu', t: 'Ur-Nammu yasaları Hammurabi\'den yaklaşık 300 yıl eskidir. Birçok suça göz için göz değil, gümüşle ödenen para cezası verir.', w: 'Code of Ur-Nammu' },
  { d: [2100, 1900], k: 'Gılgamış Destanı yazılıyor', t: 'Gılgamış hakkındaki ilk Sümerce şiirler bu dönemde yazıldı. Bilinen en eski büyük edebi eserdir; içinde bir tufan hikâyesi de vardır.', w: 'Epic of Gilgamesh' },
  // ---------- Orta Tunç Çağı ----------
  { d: [1900, 1700], k: 'Bira tanrıçasına bira tarifi', t: 'Sümerlerin "Ninkasi İlahisi", bira tanrıçasına yazılmış bir övgüdür ve içinde biranın nasıl yapılacağı adım adım anlatılır.', w: 'Ninkasi' },
  { d: [1950, 1750], k: 'Kaniş\'te Asurlu tüccarlar mektuplaşıyordu', t: 'Kayseri yakınındaki Kültepe\'de (Kaniş) Asurlu tüccarların 23.000\'den fazla tableti bulundu: Anadolu\'nun bilinen ilk yazılı belgeleri. Çoğu ticaret mektubu ve sözleşmedir.', w: 'Kültepe' },
  { d: [1780, 1740], k: 'Tarihin ilk müşteri şikâyeti', t: 'Babilli Nanni, bakır tüccarı Ea-nasir\'e kötü kalite bakır sattığı için öfkeli bir şikâyet mektubu yazdı. Tablet bugün British Museum\'da.', w: 'Complaint tablet to Ea-nasir' },
  { d: [1792, 1750], k: 'Hammurabi doktor ücretlerini de belirledi', t: 'Hammurabi Kanunları yalnızca "göze göz" demez: doktorların, inşaatçıların ve işçilerin ücretlerini, kira ve faiz kurallarını da belirler.', w: 'Code of Hammurabi' },
  { d: [1800, 1700], k: 'Bilinen en eski yemek tarifleri', t: 'Yale Üniversitesi\'ndeki Babil tabletlerinde yaklaşık 3.700 yıllık güveç ve et suyu tarifleri var. Bilinen en eski yazılı yemek tarifleri bunlardır.', w: 'Yale Babylonian Collection' },
  { d: [1650, 1550], k: 'Santorini patladı, Minos sarsıldı', t: 'Thera (Santorini) yanardağının dev patlaması bu dönemde oldu. Adanın ortası çöktü ve bugünkü kaldera oluştu; Akrotiri kenti küller altında kaldı.', w: 'Minoan eruption' },
  // ---------- Geç Tunç Çağı ----------
  { d: [1479, 1458], k: 'Kadın firavun Punt\'a sefer düzenledi', t: 'Hatşepsut, Kızıldeniz\'in güneyindeki Punt ülkesine gemiler gönderdi. Gemiler tütsü ağaçları, abanoz ve hayvanlarla döndü; sefer tapınağının duvarlarında resmedildi.', w: 'Hatshepsut' },
  { d: [1360, 1332], k: 'Firavunlar Akadca mektuplaşıyordu', t: 'Amarna mektupları, Mısır\'ın Babil, Mitanni ve Hitit krallarıyla yazışmalarıdır. Ortak diplomasi dili Mısırca değil, çivi yazılı Akadcaydı.', w: 'Amarna letters' },
  { d: [1353, 1336], k: 'Tek tanrı deneyi: Ehnaton', t: 'Firavun Ehnaton, eski tanrıları bırakıp yalnızca güneş kursu Aton\'a tapınmayı istedi ve yeni bir başkent kurdu. Ölümünden sonra adı kayıtlardan silindi.', w: 'Akhenaten' },
  { d: [1335, 1320], k: 'Tutankamon\'un hançeri gökten düştü', t: 'Tutankamon\'un mezarındaki demir hançer, 2016\'daki incelemeye göre göktaşı demirinden yapılmıştır. Demir işçiliği o çağda çok değerliydi.', w: 'Tutankhamun\'s meteoric iron dagger' },
  { d: [1279, 1213], k: 'II. Ramses 66 yıl tahtta kaldı', t: 'II. Ramses yaklaşık 66 yıl hüküm sürdü. Yüzü aşkın çocuğu olduğu sanılıyor; çocuklarının birçoğu ondan önce öldü.', w: 'Ramesses II' },
  { d: [1274, 1240], k: 'İlk barış antlaşmasının kopyası BM\'de', t: 'Hititler ile Mısır arasındaki Kadeş Antlaşması (MÖ 1259) bilinen en eski barış antlaşmalarındandır. Bir kopyası New York\'taki BM binasında asılıdır.', w: 'Egyptian–Hittite peace treaty' },
  { d: [1200, 1150], k: 'Tunç Çağı birkaç on yılda çöktü', t: 'MÖ 1200 civarında Doğu Akdeniz\'in büyük devletleri peş peşe yıkıldı: Hititler, Miken krallıkları, Ugarit. Mısır ayakta kaldı ama "Deniz Kavimleri" ile savaştı.', w: 'Late Bronze Age collapse' },
  { d: [1100, 900], k: 'Bugünkü harflerin atası Fenike alfabesi', t: 'Fenikeliler 22 harflik bir alfabe kullanıyordu. Yunan, Latin ve bugün Türkçede kullandığımız harfler bu alfabeden türedi.', w: 'Phoenician alphabet' },
  { d: [1600, 1046], k: 'Çin\'de kehanet kemikleri', t: 'Shang krallarının kâhinleri öküz kürek kemiklerine ve kaplumbağa kabuklarına soru yazıp ateşte çatlatırdı. Bu yazılar Çince\'nin bilinen en eski örnekleridir.', w: 'Oracle bone' },
  // ---------- Demir Çağı ----------
  { d: [780, 720], k: 'İlk Olimpiyat\'ta tek yarış vardı', t: 'Kayıtlara göre MÖ 776\'daki ilk Olimpiyat Oyunları\'nda yalnızca bir koşu yapıldı: yaklaşık 192 metrelik "stadion" yarışı.', w: 'Ancient Olympic Games' },
  { d: [760, 700], k: 'Roma kurulurken piramitler 1.800 yaşındaydı', t: 'Geleneğe göre Roma MÖ 753\'te kuruldu. O gün Gize\'deki Büyük Piramit zaten 1.800 yaşındaydı.', w: 'Founding of Rome' },
  { d: [740, 700], k: 'Kral Midas gerçekten yaşadı', t: 'Altın dokunuşlu Midas efsanesinin arkasında gerçek bir Frig kralı var: Mita. Asur kayıtlarında adı geçer; Gordion\'daki dev tümülüs onun ailesine aittir.', w: 'Midas' },
  { d: [668, 627], k: 'Yangın, kütüphaneyi kurtardı', t: 'Asur kralı Asurbanipal Ninova\'da büyük bir kütüphane kurdu. MÖ 612\'de kent yakılınca kil tabletler pişip sertleşti; Gılgamış Destanı böylece günümüze ulaştı.', w: 'Library of Ashurbanipal' },
  { d: [650, 560], k: 'Para Anadolu\'da icat edildi', t: 'Bilinen ilk madeni paralar Lidya\'da, altın-gümüş alaşımından basıldı. Kroisos döneminde saf altın ve gümüş sikkeler de çıktı.', w: 'Lydia' },
  { d: [590, 580], k: 'Güneş tutuldu, savaş durdu', t: 'Herodot\'a göre MÖ 585\'te Lidyalılar ile Medler savaşırken güneş tutuldu. Askerler bunu bir işaret sayıp barış yaptı; tutulmayı Thales önceden bildirmişti.', w: 'Battle of the Eclipse' },
  { d: [604, 562], k: 'Babil\'in mavi kapısı', t: 'II. Nebukadnezar, Babil\'e parlak mavi sırlı tuğlalarla İştar Kapısı\'nı yaptırdı. Kapı bugün Berlin\'deki Bergama Müzesi\'nde yeniden kurulmuş durumda.', w: 'Ishtar Gate' },
  { d: [604, 562], k: 'Asma Bahçeler hiç var olmamış olabilir', t: 'Babil\'in Asma Bahçeleri dünyanın yedi harikasından sayılır ama hiçbir Babil yazıtında geçmez. Bazı tarihçiler bahçelerin aslında Ninova\'da olduğunu düşünür.', w: 'Hanging Gardens of Babylon' },
  { d: [560, 480], k: 'Buda, Konfüçyüs ve Pisagor çağdaştı', t: 'Konfüçyüs (MÖ 551–479) ve Pisagor (yaklaşık MÖ 570–495) aynı yüzyılda yaşadı. Buda\'nın tarihleri tartışmalı ama büyük olasılıkla o da aynı çağa yakındır.', w: 'Axial Age' },
  { d: [539, 530], k: 'Kiros Silindiri', t: 'Pers kralı Büyük Kiros Babil\'i aldıktan sonra bir kil silindir yazdırdı: sürgün halkların evlerine dönebileceğini anlatır. Silindir British Museum\'dadır.', w: 'Cyrus Cylinder' },
  { d: [518, 465], k: 'Persepolis\'te doğum izni vardı', t: 'Persepolis tabletleri işçilere verilen tayınları kaydeder. Doğum yapan kadın işçiler ek tayın alırdı; kadın ve erkek ustalar ücret alıyordu.', w: 'Persepolis Administrative Archives' },
  { d: [500, 330], k: 'Postacıların sloganı Herodot\'tan', t: 'Herodot, Pers kraliyet yolundaki atlı ulakları "ne kar, ne yağmur, ne sıcak durdurur" diye anlatır. Bu söz bugün New York\'taki büyük postanenin cephesinde yazılıdır.', w: 'Royal Road' },
  { d: [490, 416], k: 'Çanak çömlek kırığıyla sürgün oylaması', t: 'Atinalılar tehlikeli buldukları bir politikacının adını kırık çanak parçalarına (ostrakon) yazardı. Yeterli oy çıkarsa kişi 10 yıl sürgüne giderdi.', w: 'Ostracism' },
  { d: [450, 320], k: 'Atina\'da jüriyi makine seçerdi', t: 'Atina demokrasisinde görevliler ve jüri üyeleri kurayla seçilirdi. Bunun için "kleroterion" adlı, delikli taş bir kura makinesi kullanılırdı.', w: 'Kleroterion' },
  { d: [470, 399], k: 'Sokrates tek satır yazmadı', t: 'Felsefenin en ünlü adlarından Sokrates hiçbir şey yazmadı. Onu öğrencisi Platon\'un ve Ksenofon\'un yazdıklarından tanıyoruz.', w: 'Socrates' },
  { d: [450, 420], k: '"Tarihin babası" Bodrumlu', t: 'Tarih yazıcılığının babası sayılan Herodot, bugünkü Bodrum olan Halikarnassos\'ta doğdu.', w: 'Herodotus' },
  { d: [377, 350], k: 'Mozole sözcüğü Bodrum\'dan geliyor', t: 'Karya kralı Mausolos için Halikarnassos\'ta yapılan dev anıt mezar dünyanın yedi harikasından biriydi. Bugünkü "mozole" sözcüğü onun adından gelir.', w: 'Mausoleum at Halicarnassus' },
  { d: [343, 323], k: 'İskender\'in öğretmeni Aristoteles', t: 'Makedonya kralı II. Filip, oğlu İskender\'e ders vermesi için filozof Aristoteles\'i tuttu. İskender 13 yaşındaydı.', w: 'Alexander the Great' },
  { d: [323, 280], k: 'İskender\'in ölümü bir dünyayı böldü', t: 'İskender MÖ 323\'te 32 yaşında Babil\'de öldü. Komutanları imparatorluğu paylaştı: Mısır\'da Ptolemaioslar, Asya\'da Selevkoslar kuruldu.', w: 'Diadochi' },
  { d: [268, 232], k: 'Savaştan pişman olan imparator', t: 'Maurya imparatoru Aşoka, Kalinga savaşındaki ölümlerden sonra pişman oldu ve Budizm\'e yöneldi. Fermanlarını kayalara ve sütunlara kazıttı.', w: 'Ashoka' },
  { d: [245, 194], k: 'Dünyanın çevresini bir gölgeyle ölçtü', t: 'İskenderiyeli Eratosthenes, iki şehirdeki gölge farkından yararlanarak Dünya\'nın çevresini şaşırtıcı bir yakınlıkla hesapladı.', w: 'Eratosthenes' },
  { d: [221, 206], k: '8.000 pişmiş topraktan asker', t: 'Çin\'i birleştiren ilk imparator Qin Shi Huang, mezarına yaklaşık 8.000 pişmiş toprak asker, at ve savaş arabası koydurdu. 1974\'te köylüler kuyu kazarken buldu.', w: 'Terracotta Army' },
  { d: [218, 216], k: 'Hannibal Alpleri 37 fille aştı', t: 'Kartacalı Hannibal, Polybios\'a göre 37 savaş filiyle Alpleri aşıp İtalya\'ya indi. Fillerin çoğu soğuk ve savaş yüzünden kısa sürede öldü.', w: 'Hannibal\'s crossing of the Alps' },
  { d: [214, 212], k: 'Arşimet çizimlerinin başında öldü', t: 'Siraküza kuşatmasında Romalı bir asker Arşimet\'i öldürdü. Anlatılana göre son sözü "Çemberlerimi bozma!" olmuştur.', w: 'Archimedes' },
  { d: [200, 150], k: 'Parşömen Bergama\'nın adını taşır', t: 'Bergama Kütüphanesi İskenderiye ile yarışıyordu. "Parşömen" sözcüğü Bergama\'nın eski adı Pergamon\'dan gelir; kent bu yazı malzemesiyle ünlüydü.', w: 'Parchment' },
  { d: [196, 190], k: 'Rosetta Taşı aslında bir vergi kararnamesi', t: 'Hiyerogliflerin çözülmesini sağlayan Rosetta Taşı, MÖ 196\'da rahiplerin V. Ptolemaios için yazdığı bir kararnamedir; aynı metin üç yazıyla yazılmıştır.', w: 'Rosetta Stone' },
  { d: [150, 60], k: 'Antik Yunan\'ın "bilgisayarı"', t: 'Antikythera düzeneği, bronz dişlilerle Güneş\'in, Ay\'ın ve tutulmaların yerini hesaplayan bir alettir. Benzeri ancak 1.000 yıldan fazla sonra yapılabildi.', w: 'Antikythera mechanism' },
  { d: [76, 74], k: 'Sezar fidyesinin artırılmasını istedi', t: 'Plutarkhos\'a göre genç Sezar\'ı korsanlar kaçırıp 20 talant fidye istedi. Sezar kendine hakaret sayıp 50 talant istemelerini söyledi.', w: 'Julius Caesar' },
  { d: [69, 30], k: 'Kleopatra bize piramitlerden daha yakın', t: 'Kleopatra, Büyük Piramit\'in yapılışından yaklaşık 2.500 yıl sonra yaşadı. Ay\'a inişe (1969) ise yaklaşık 2.000 yıl uzaktı.', w: 'Cleopatra' },
  { d: [47, 44], k: '445 günlük yıl', t: 'Sezar takvimi düzeltirken birikmiş kaymayı kapatmak için MÖ 46 yılını 445 gün yaptı. Romalılar ona "karışıklık yılı" dedi.', w: 'Julian calendar' },
  { d: [30, 1], k: 'Roma\'nın nüfusu 1 milyona yaklaştı', t: 'Augustus döneminde Roma\'nın nüfusu yaklaşık bir milyon olarak tahmin edilir. Avrupa\'da bu büyüklüğe yeniden ulaşan ilk şehir 1800\'lerde Londra oldu.', w: 'Ancient Rome' },
  { d: [6, -10], k: 'İsa büyük olasılıkla "MÖ"de doğdu', t: 'Takvimi MS 525\'te hesaplayan keşiş Dionysius Exiguus yanıldı. Tarihçilere göre İsa büyük olasılıkla MÖ 6–4 arasında doğdu.', w: 'Anno Domini' },
  // ---------- Roma ve Han ----------
  { d: [-14, -37], k: 'Roma\'da erkeklere ipek yasağı', t: 'Tacitus\'a göre Tiberius döneminde senato erkeklerin ipek giymesini yasakladı. İpek Çin\'den geliyordu ve Roma\'nın altını doğuya akıyordu.', w: 'Sumptuary law' },
  { d: [-37, -41], k: 'Caligula\'nın atı ve konsülluk', t: 'Suetonius\'a göre imparator Caligula, sevdiği atı Incitatus\'u konsül yapmayı planlıyordu. At mermer ahırda yaşıyor, fildişi yemlikten yiyordu.', w: 'Incitatus' },
  { d: [-60, -79], k: 'Pompeii duvarlarında seçim afişleri', t: 'MS 79\'da Vezüv\'ün küllerine gömülen Pompeii\'nin duvarlarında seçim çağrıları, reklamlar, aşk notları ve şakalar korunmuştur.', w: 'Pompeii' },
  { d: [-80, -90], k: 'Kolezyum\'da deniz savaşı', t: 'Cassius Dio\'ya göre Kolezyum\'un açılış oyunlarında arena suyla doldurulup küçük bir deniz savaşı canlandırıldı.', w: 'Naumachia' },
  { d: [-105, -130], k: 'Kâğıdı bir saray görevlisi geliştirdi', t: 'Çinli saray görevlisi Cai Lun, MS 105\'te ağaç kabuğu, kenevir ve paçavradan kâğıt yapımını geliştirip imparatora sundu.', w: 'Cai Lun' },
  { d: [-113, -200], k: 'Pantheon\'un kubbesi hâlâ rekor', t: 'Roma\'daki Pantheon\'un kubbesi yaklaşık MS 126\'da bitti. Demir donatısız betondan yapılmış dünyanın en büyük kubbesi olmaya bugün de devam ediyor.', w: 'Pantheon, Rome' },
  { d: [-122, -138], k: 'Britanya\'yı kesen 117 km\'lik duvar', t: 'İmparator Hadrianus, Britanya\'nın kuzeyine kıyıdan kıyıya 117 km\'lik bir duvar yaptırdı. Roma\'nın kuzey sınırıydı.', w: 'Hadrian\'s Wall' },
  { d: [-125, -140], k: 'Deprem ölçen bronz kap', t: 'Çinli bilgin Zhang Heng MS 132\'de deprem yönünü gösteren bir alet yaptı: sarsıntıda ejderhanın ağzındaki bilye bir kurbağanın ağzına düşerdi.', w: 'Zhang Heng' },
  { d: [-160, -175], k: 'Roma\'dan Çin\'e elçi', t: 'Çin kayıtlarına göre MS 166\'da "Daqin" (Roma) imparatoru Andun\'un elçileri Han sarayına geldi. Andun\'un Marcus Aurelius Antoninus olduğu düşünülür.', w: 'Sino-Roman relations' },
  { d: [-100, -300], k: 'Roma yolları 400.000 km', t: 'Roma İmparatorluğu\'nun yol ağı yaklaşık 400.000 km\'ydi; bunun 80.000 km\'den fazlası taş döşeliydi. Bazıları bugün hâlâ kullanılıyor.', w: 'Roman roads' },
  { d: [48, -400], k: 'İskenderiye Kütüphanesi tek gecede yanmadı', t: 'Yaygın inanışın aksine İskenderiye Kütüphanesi tek bir büyük yangında yok olmadı. Yüzyıllar boyunca para ve ilgi azaldıkça yavaş yavaş söndü.', w: 'Library of Alexandria' },
  { d: [-250, -900], k: 'Mayalar sıfırı kullanıyordu', t: 'Mayalar en geç MS 4. yüzyılda takvim hesaplarında sıfırı kullanıyordu. Avrupa\'da sıfır ancak 13. yüzyılda yaygınlaşmaya başladı.', w: '0' },
  { d: [-261, -272], k: 'Roma\'ya kafa tutan kraliçe Zenobia', t: 'Palmira kraliçesi Zenobia, Mısır\'dan Anadolu\'ya uzanan bir devlet kurdu. MS 272\'de Roma imparatoru Aurelianus\'a yenildi.', w: 'Zenobia' },
  { d: [-300, -550], k: 'Teotihuacan Avrupa\'nın çoğu kentinden büyüktü', t: 'Meksika\'daki Teotihuacan, MS 500 civarında 100.000\'i aşkın nüfusuyla dünyanın en büyük şehirlerinden biriydi.', w: 'Teotihuacan' },
  { d: [-324, -337], k: 'Bizans 330\'da yeni Roma oldu', t: 'Konstantin, Byzantion\'u büyüterek MS 330\'da imparatorluğun yeni başkenti ilan etti. Kent bin yıldan uzun süre Konstantinopolis adıyla anıldı.', w: 'Constantinople' },
  { d: [-330, -356], k: 'Aksum, Hristiyanlığı ilk benimseyenlerden', t: 'Etiyopya\'daki Aksum Krallığı, Kral Ezana döneminde 4. yüzyılda Hristiyanlığı kabul etti. Aksum kendi altın sikkelerini basan az sayıdaki Afrika devletindendi.', w: 'Kingdom of Aksum' },
  { d: [-427, -600], k: 'Nalanda: binlerce öğrencili üniversite', t: 'Hindistan\'daki Nalanda, 5. yüzyılda kurulan büyük bir öğrenim merkeziydi. Çin\'den, Kore\'den ve Orta Asya\'dan öğrenciler gelirdi.', w: 'Nalanda mahavihara' },
  { d: [-450, -453], k: 'Attila düğün gecesi öldü', t: 'Hun hükümdarı Attila MS 453\'te yeni evlendiği gece burnu kanayarak öldü. Mezarının yeri hâlâ bilinmiyor.', w: 'Attila' },
  { d: [-476, -480], k: 'Batı Roma\'nın son imparatoru bir gençti', t: 'Batı Roma\'nın son imparatoru Romulus Augustulus henüz bir gençken 476\'da tahttan indirildi. Adı küçümsemeyle "küçük Augustus" anlamına gelir.', w: 'Romulus Augustulus' },
  // ---------- Erken Orta Çağ ----------
  { d: [-532, -560], k: 'Ayasofya bin yıl en büyük katedraldi', t: 'Ayasofya yalnızca yaklaşık 5 yılda yapılıp 537\'de açıldı. Yaklaşık 1.000 yıl boyunca dünyanın en büyük katedrali olarak kaldı.', w: 'Hagia Sophia' },
  { d: [-536, -540], k: '536: yaşamak için en kötü yıl', t: 'MS 536\'da büyük olasılıkla bir yanardağ patlaması yüzünden güneş bir yıldan uzun süre soluk parladı. Avrupa\'dan Çin\'e kadar ürünler yetişmedi.', w: 'Volcanic winter of 536' },
  { d: [-541, -549], k: 'Justinianus vebası', t: '541\'de başlayan veba salgını Konstantinopolis\'te günde binlerce kişiyi öldürdü. Tarihte kaydı tutulan ilk büyük veba salgınıdır.', w: 'Plague of Justinian' },
  { d: [-550, -560], k: 'İpek böceği bastonlarda kaçırıldı', t: 'Prokopios\'a göre 6. yüzyılda iki keşiş, ipek böceği yumurtalarını içi oyuk bastonlarda saklayıp Orta Asya\'dan Bizans\'a getirdi. İpeğin sırrı böylece Çin\'in tekelinden çıktı.', w: 'History of silk' },
  { d: [-550, -650], k: 'Satranç Hindistan\'da doğdu', t: 'Satrancın atası sayılan "çaturanga" Gupta döneminden sonra, 6. yüzyıl civarında Hindistan\'da oynanıyordu. Oyun İran üzerinden İslam dünyasına ve Avrupa\'ya geçti.', w: 'Chaturanga' },
  { d: [-618, -632], k: 'Hicret yılında Tang Çin\'i yeni kurulmuştu', t: 'Hz. Muhammed 622\'de Medine\'ye hicret ettiğinde Çin\'de Tang Hanedanı yalnızca dört yıllıktı (618).', w: 'Tang dynasty' },
  { d: [-650, -750], k: 'Chang\'an: dünyanın en büyük kenti', t: 'Tang başkenti Chang\'an\'ın (bugünkü Xi\'an) nüfusunun 1 milyona yaklaştığı sanılıyor. Dünyanın en kalabalık şehriydi.', w: 'Chang\'an' },
  { d: [-690, -705], k: 'Çin\'in tek kadın imparatoru', t: 'Wu Zetian 690\'da kendi hanedanını ilan edip Çin\'in resmî unvanlı tek kadın imparatoru oldu.', w: 'Wu Zetian' },
  { d: [-720, -735], k: 'En eski Türkçe yazıtlar', t: 'Moğolistan\'daki Orhun Yazıtları (Bilge Kağan ve Kül Tigin için, 732–735) bilinen en eski uzun Türkçe metinlerdendir.', w: 'Orkhon inscriptions' },
  { d: [-751, -760], k: 'Kâğıt, Talas\'tan sonra batıya geçti', t: 'Rivayete göre 751\'deki Talas Savaşı\'nda esir alınan Çinli ustalar Semerkant\'ta kâğıt yapmayı öğretti. Kâğıt oradan Bağdat\'a ve Avrupa\'ya yayıldı.', w: 'Battle of Talas' },
  { d: [-762, -770], k: 'Bağdat yuvarlak bir şehir olarak kuruldu', t: 'Abbasi halifesi Mansur, Bağdat\'ı 762\'de üç sıra surla çevrili, tam daire planlı bir şehir olarak kurdurdu.', w: 'Round city of Baghdad' },
  { d: [-768, -814], k: 'Şarlman yazmayı öğrenemedi', t: 'Biyografisini yazan Einhard\'a göre Şarlman ileri yaşta yazı yazmayı denedi ama başaramadı. Buna rağmen okulları ve kitap kopyalamayı destekledi.', w: 'Charlemagne' },
  { d: [-797, -810], k: 'Harun Reşid Şarlman\'a fil yolladı', t: 'Abbasi halifesi Harun Reşid, Şarlman\'a Ebu\'l-Abbas adlı bir fil hediye etti. Fil 802\'de Aachen\'e ulaştı.', w: 'Abul-Abbas' },
  { d: [-813, -850], k: '"Algoritma" bir bilginin adından', t: 'Bağdat\'taki Beytü\'l-Hikme\'de çalışan Harezmi\'nin adı Latinceye "Algoritmi" diye geçti; bugünkü "algoritma" sözcüğü buradan gelir. "Cebir" de onun kitabından.', w: 'Muhammad ibn Musa al-Khwarizmi' },
  { d: [-850, -900], k: 'Barut ölümsüzlük iksiri ararken bulundu', t: 'Çinli simyacılar 9. yüzyılda ölümsüzlük iksiri ararken güherçile, kükürt ve kömür karışımının yandığını keşfetti. Böylece barut doğdu.', w: 'Gunpowder' },
  { d: [-859, -880], k: 'Hâlâ açık en eski üniversiteyi bir kadın kurdu', t: 'Fas\'taki Karaviyyin\'i 859\'da Fatıma el-Fihri kurdu. UNESCO\'ya göre kesintisiz eğitim veren en eski kurumdur.', w: 'University of al-Qarawiyyin' },
  { d: [-860, -880], k: 'Tarihli ilk basılı kitap', t: 'Çin\'de tahta kalıplarla basılan Elmas Sutra 868 tarihini taşır. Üzerinde tarih yazan bilinen en eski basılı kitaptır.', w: 'Diamond Sutra' },
  { d: [-850, -1100], k: 'Ayasofya\'da Viking yazısı', t: 'Ayasofya\'nın üst galerisindeki mermer korkuluğa Halfdan adlı bir Viking run harfleriyle adını kazımış. Vikingler Bizans imparatorunun muhafızı olarak çalışıyordu.', w: 'Varangian Guard' },
  { d: [-986, -990], k: 'Ruslar dinlerini nasıl seçti', t: 'Rus Vakayinamesi\'ne göre Kiev prensi Vladimir dinleri araştırdı; İslam\'ı içki yasağı yüzünden reddetti ve 988\'de Bizans Hristiyanlığını seçti.', w: 'Christianization of Kievan Rus\'' },
  // ---------- Yüksek Orta Çağ ----------
  { d: [-1000, -1025], k: 'Vikingler Amerika\'da, Kolomb\'dan 471 yıl önce', t: 'Kanada\'daki L\'Anse aux Meadows\'da bulunan Viking yerleşiminde ağaçlar 1021\'de kesilmiş. Bu, Kolomb\'dan 471 yıl önce Avrupalıların Amerika\'da olduğunu kanıtlıyor.', w: 'L\'Anse aux Meadows' },
  { d: [-1014, -1018], k: '"Bulgar Avcısı" Basileios', t: 'Bizans imparatoru II. Basileios 1014\'te yendiği Bulgar ordusunun askerlerini kör ettirdi; kaynaklar 14.000–15.000 kişiden söz eder. Bu yüzden "Bulgar Avcısı" diye anıldı.', w: 'Basil II' },
  { d: [-1020, -1050], k: 'Kâğıt para Çin\'de doğdu', t: 'Song Çin\'i 1024\'te devlet eliyle basılan ilk kâğıt parayı (jiaozi) çıkardı. Avrupa\'da kâğıt para ancak 17. yüzyılda yaygınlaştı.', w: 'Jiaozi (currency)' },
  { d: [-1020, -1037], k: 'İbn Sina\'nın kitabı 600 yıl okutuldu', t: 'İbn Sina\'nın "Tıp Kanunu" Latinceye çevrildi ve Avrupa üniversitelerinde 17. yüzyıla kadar ders kitabı olarak kullanıldı.', w: 'The Canon of Medicine' },
  { d: [-1072, -1077], k: 'Kaşgarlı Mahmud\'un dünya haritası', t: 'Kaşgarlı Mahmud, Divanü Lügati\'t-Türk\'ü 1070\'lerde Bağdat\'ta yazdı. Kitapta Türklerin yaşadığı toprakları gösteren yuvarlak bir dünya haritası da var.', w: 'Dīwān Lughāt al-Turk' },
  { d: [-1074, -1092], k: 'Ömer Hayyam\'ın takvimi bizimkinden hassas', t: 'Şair ve matematikçi Ömer Hayyam\'ın da çalıştığı Celali takvimi, Selçuklu sultanı Melikşah için hazırlandı. Bugün kullandığımız Gregoryen takviminden daha hassastır.', w: 'Jalali calendar' },
  { d: [-1096, -1167], k: 'Oxford, Aztek İmparatorluğu\'ndan eski', t: 'Oxford\'da ders verilmeye 1096 civarında başlandı. Aztek başkenti Tenochtitlan ise ancak 1325\'te kuruldu.', w: 'University of Oxford' },
  { d: [-1100, -1130], k: 'Pusulayla ilk deniz yolculukları', t: 'Çinli Zhu Yu\'nun 1119 tarihli kitabı, gemicilerin bulutlu havada yön bulmak için pusula kullandığını yazar. Bu, pusulanın denizcilikte kullanıldığının bilinen ilk kaydıdır.', w: 'Compass' },
  { d: [-1113, -1150], k: 'Angkor Wat: dünyanın en büyük tapınağı', t: 'Kamboçya\'daki Angkor Wat 12. yüzyılın başında yapıldı. Dünyanın en büyük dinî yapısıdır ve Kamboçya bayrağında yer alır.', w: 'Angkor Wat' },
  { d: [-1163, -1260], k: 'Notre-Dame\'ın yapımı 180 yıl sürdü', t: 'Paris\'teki Notre-Dame Katedrali\'nin temeli 1163\'te atıldı; yapı ancak 1345 civarında tamamlandı.', w: 'Notre-Dame de Paris' },
  { d: [-1173, -1280], k: 'Pisa Kulesi yapılırken eğildi', t: 'Pisa Kulesi, 1178\'de ikinci kat bittiğinde yumuşak zemin yüzünden eğilmeye başladı. Yapım savaşlar yüzünden 200 yıla yayıldı.', w: 'Leaning Tower of Pisa' },
  { d: [-1181, -1221], k: 'Tek kayadan oyulmuş kiliseler', t: 'Etiyopya\'daki Lalibela kiliseleri yukarıdan aşağıya, tek parça kayanın içi oyularak yapıldı.', w: 'Lalibela' },
  { d: [-1200, -1280], k: 'Selçuklu hanları bir günlük yol arayla', t: 'Anadolu Selçukluları kervan yollarına yaklaşık 30–40 km arayla, yani bir deve kervanının günlük yürüyüşü kadar arayla kervansaraylar yaptırdı.', w: 'Caravanserai' },
  { d: [-1206, -1294], k: 'Tarihin en büyük kara imparatorluğu', t: 'Moğol İmparatorluğu Kore\'den Macaristan sınırına kadar uzandı. Toprakları birbirine bitişik en büyük imparatorluktur.', w: 'Mongol Empire' },
  { d: [-1215, -1217], k: 'Magna Carta', t: 'İngiltere kralı John, baronların baskısıyla 1215\'te Magna Carta\'yı imzaladı. Kralın da yasaya bağlı olduğu fikrinin simgesi oldu.', w: 'Magna Carta' },
  { d: [-1250, -1320], k: 'Yeni Zelanda\'ya insanlar en son geldi', t: 'Polinezyalı denizciler Yeni Zelanda\'ya ancak 1250–1300 civarında yerleşti. Burası insanların yerleştiği son büyük kara parçalarındandır.', w: 'History of New Zealand' },
  { d: [-1250, -1500], k: 'Paskalya Adası\'nın 900 heykeli', t: 'Paskalya Adası\'nda (Rapa Nui) yaklaşık 900 moai heykeli yapıldı. Çoğu yanardağ taşından oyulup adanın içlerinden taşındı.', w: 'Moai' },
  { d: [-1271, -1295], k: 'Marco Polo kâğıt paraya şaştı', t: 'Marco Polo, Kubilay Han\'ın Çin\'inde dut ağacı kabuğundan yapılan kâğıt paranın her yerde geçmesine hayret ettiğini yazar.', w: 'Marco Polo' },
  { d: [-1274, -1281], k: 'Japonya\'yı "kamikaze" kurtardı', t: 'Kubilay Han\'ın Japonya seferlerini 1274 ve 1281\'de fırtınalar dağıttı. Japonlar bu fırtınalara "kamikaze" (ilahi rüzgâr) dedi.', w: 'Mongol invasions of Japan' },
  { d: [-1299, -1321], k: 'Osman Bey ile Dante aynı yıllarda', t: 'Osmanlı Beyliği büyürken İtalya\'da Dante "İlahi Komedya"yı yazıyordu (yaklaşık 1308–1321).', w: 'Divine Comedy' },
  { d: [-1100, -1450], k: 'Büyük Zimbabve harçsız örüldü', t: 'Büyük Zimbabve\'nin taş duvarları hiç harç kullanılmadan, taşlar özenle üst üste dizilerek yapıldı. Ülkenin adı da bu yapılardan gelir.', w: 'Great Zimbabwe' },
  // ---------- Geç Orta Çağ ----------
  { d: [-1324, -1330], k: 'Mansa Musa altın fiyatını düşürdü', t: 'Mali hükümdarı Mansa Musa 1324\'te hacca giderken Kahire\'de o kadar çok altın harcadı ki, el-Ömeri\'ye göre altının değeri yıllarca düşük kaldı.', w: 'Mansa Musa' },
  { d: [-1325, -1354], k: 'İbn Battuta 117.000 km yol yaptı', t: 'Faslı gezgin İbn Battuta yaklaşık 30 yılda Afrika\'dan Çin\'e 117.000 km yol katetti. Marco Polo\'nun yolundan çok daha uzundur.', w: 'Ibn Battuta' },
  { d: [-1325, -1340], k: 'Meksika bayrağındaki kartal efsanesi', t: 'Efsaneye göre Aztekler, kaktüs üstünde yılan yiyen bir kartal gördükleri göl adasında 1325\'te Tenochtitlan\'ı kurdu. Bu sahne bugün Meksika bayrağında.', w: 'Tenochtitlan' },
  { d: [-1337, -1453], k: 'Yüz Yıl Savaşı 116 yıl sürdü', t: 'İngiltere ile Fransa arasındaki Yüz Yıl Savaşı aslında 1337\'den 1453\'e kadar, 116 yıl sürdü.', w: 'Hundred Years\' War' },
  { d: [-1347, -1353], k: 'Kara Ölüm Avrupa\'nın üçte birini öldürdü', t: 'Kara Ölüm (veba) 1347–1351 arasında Avrupa nüfusunun yaklaşık üçte biri ile yarısı arasında bir kısmını öldürdü.', w: 'Black Death' },
  { d: [-1400, -1600], k: 'Timbuktu\'nun yüz binlerce el yazması', t: 'Mali\'deki Timbuktu bir bilim ve kitap şehriydi. Astronomi, tıp ve hukuk konulu yüz binlerce el yazması günümüze ulaştı.', w: 'Timbuktu Manuscripts' },
  { d: [-1405, -1433], k: 'Zheng He\'nin dev filosu', t: 'Çinli amiral Zheng He 1405\'te yaklaşık 300 gemi ve 28.000 denizciyle yola çıktı ve Doğu Afrika\'ya kadar gitti. Kolomb\'un üç gemisinden 87 yıl önce.', w: 'Zheng He' },
  { d: [-1420, -1449], k: 'Uluğ Bey\'in yıldız kataloğu', t: 'Timur\'un torunu Uluğ Bey, Semerkant\'ta dev bir gözlemevi kurdu. 1.000\'i aşkın yıldızın yerini o çağ için olağanüstü bir doğrulukla ölçtü.', w: 'Ulugh Beg Observatory' },
  { d: [-1429, -1431], k: 'Jeanne d\'Arc 19 yaşında yakıldı', t: 'Fransız ordusuna önderlik eden köylü kızı Jeanne d\'Arc 1431\'de 19 yaşında yakılarak idam edildi.', w: 'Joan of Arc' },
  { d: [-1438, -1533], k: 'İnkalar düğümlü iplerle kayıt tuttu', t: 'İnkaların yazısı yoktu ama "kipu" denen renkli düğümlü iplerle vergi, nüfus ve ambar kayıtları tutuyorlardı.', w: 'Quipu' },
  { d: [-1443, -1450], k: 'Bir kral yeni bir alfabe icat etti', t: 'Kore kralı Sejong, halkın kolayca okuyabilmesi için 1443\'te Hangıl alfabesini oluşturdu. Bugün Korece bu alfabeyle yazılıyor.', w: 'Hangul' },
  { d: [-1450, -1460], k: '1453: iki savaş aynı yıl bitti', t: '1453\'te Mayıs ayında İstanbul fethedildi; Temmuz\'da da Castillon Muharebesi\'yle Yüz Yıl Savaşı sona erdi.', w: '1453' },
  { d: [-1450, -1460], k: 'Gutenberg İncili basıldı', t: 'Gutenberg hareketli metal harflerle İncil\'i yaklaşık 1455\'te bastı. Avrupa\'da kitap üretimi birkaç on yılda patladı.', w: 'Gutenberg Bible' },
  { d: [-1450, -1572], k: 'İspanyollar Machu Picchu\'yu hiç bulamadı', t: 'Machu Picchu, İnka hükümdarı Pachacuti için 1450 civarında yapıldı. İspanyol fatihler buraya hiç ulaşmadı; dünya kenti 1911\'den sonra tanıdı.', w: 'Machu Picchu' },
  { d: [-1450, -1533], k: 'İnka yolları 40.000 km', t: 'İnka yol ağı And Dağları boyunca yaklaşık 40.000 km uzanıyordu. Bayrak yarışı yapan ulaklar (çaski) haberleri günde yüzlerce kilometre taşırdı.', w: 'Inca road system' },
  { d: [-1400, -1521], k: 'Aztekler kakaoyu para olarak kullandı', t: 'Aztek pazarlarında kakao çekirdekleri para gibi kullanılırdı. Çikolata ise acı ve baharatlı bir içecek olarak içilirdi.', w: 'Cocoa bean' },
  { d: [-1470, -1600], k: 'Topkapı\'nın dev Çin porseleni koleksiyonu', t: 'Topkapı Sarayı\'ndaki Çin porseleni koleksiyonu, Çin dışındaki en büyük koleksiyonlardan biridir; 10.000\'i aşkın parça içerir.', w: 'Topkapı Palace' },
  // ---------- Keşifler çağı ----------
  { d: [-1492, -1493], k: '1492: Kolomb ve Sefarad Yahudileri', t: '1492\'de Kolomb Amerika\'ya ulaştı; aynı yıl İspanya\'dan kovulan Yahudilerin bir kısmını II. Bayezid Osmanlı topraklarına kabul etti.', w: 'Alhambra Decree' },
  { d: [-1497, -1499], k: 'Vasco da Gama Hindistan\'a deniz yolunu buldu', t: 'Vasco da Gama 1498\'de Afrika\'yı dolaşarak Hindistan\'ın Kalikut limanına ulaştı. Baharat ticareti yön değiştirmeye başladı.', w: 'Vasco da Gama' },
  { d: [-1500, -1521], k: 'Tenochtitlan Avrupa kentlerinden kalabalıktı', t: 'İspanyollar 1519\'da Tenochtitlan\'a vardığında kentin nüfusu 200.000 civarındaydı. O dönemde Avrupa\'nın çok az şehri bu büyüklükteydi.', w: 'Tenochtitlan' },
  { d: [-1500, -1510], k: 'Leonardo, Haliç\'e köprü önerdi', t: 'Leonardo da Vinci, Mona Lisa\'ya başlamadan bir yıl önce II. Bayezid\'e Haliç üzerine tek kemerli bir köprü önerdi (1502). Köprü yapılmadı ama çizimi bugün de duruyor.', w: 'Leonardo da Vinci' },
  { d: [-1510, -1520], k: 'Piri Reis\'in Amerika haritası', t: 'Piri Reis 1513\'te Amerika kıyılarını da gösteren bir dünya haritası çizdi. Haritanın bir parçası bugün Topkapı Sarayı\'nda.', w: 'Piri Reis map' },
  { d: [-1516, -1518], k: '1517: Luther ve Kahire', t: 'Yavuz Sultan Selim 1517\'de Kahire\'yi aldı; aynı yıl Almanya\'da Martin Luther 95 tezini yayımladı ve Reform başladı.', w: 'Ottoman–Mamluk War (1516–1517)' },
  { d: [-1519, -1522], k: 'Dünya turundan 270 kişiden 18\'i döndü', t: 'Macellan\'ın filosu 1519\'da yaklaşık 270 kişiyle yola çıktı. 1522\'de yalnızca bir gemi ve 18 kişi dönebildi; Macellan Filipinler\'de öldü.', w: 'Magellan expedition' },
  { d: [-1519, -1521], k: 'Kanuni tahta çıkarken Aztekler düşüyordu', t: 'Kanuni Sultan Süleyman 1520\'de tahta çıktığında, Cortés okyanusun öbür yakasında Aztek İmparatorluğu\'nu yıkıyordu (1519–1521).', w: 'Spanish conquest of the Aztec Empire' },
  { d: [-1520, -1566], k: 'En uzun saltanat: Kanuni', t: 'Kanuni Sultan Süleyman 46 yıl tahtta kaldı; en uzun hüküm süren Osmanlı padişahıdır.', w: 'Suleiman the Magnificent' },
  { d: [-1520, -1560], k: 'Hindi mi, Turkey mi?', t: 'Amerika\'dan gelen kuşa Türkler "hindi" (Hindistan\'dan) dedi, İngilizler "turkey" (Türkiye\'den) ve Fransızlar "dinde" (d\'Inde). Kimse nereden geldiğini bilmiyordu.', w: 'Domestic turkey' },
  { d: [-1500, -1600], k: 'Hint yemeklerinde acı biber yoktu', t: 'Acı biber Amerika\'dan geldi ve Hindistan\'a 16. yüzyılda Portekizlilerle ulaştı. Ondan önce Hint mutfağı karabiber ve zencefil kullanıyordu.', w: 'Chili pepper' },
  { d: [-1540, -1600], k: 'İtalyan mutfağında domates yoktu', t: 'Domates Amerika\'dan 16. yüzyılda geldi ve Avrupa\'da uzun süre süs bitkisi sayıldı. Domatesli makarna sosu ancak 1700\'lerde yaygınlaştı.', w: 'Tomato' },
  { d: [-1543, -1550], k: '1543: Dünya döndü, beden açıldı', t: 'Kopernik, Dünya\'nın Güneş\'in çevresinde döndüğünü anlatan kitabını 1543\'te yayımladı. Aynı yıl Vesalius ilk ayrıntılı insan anatomisi kitabını bastı.', w: 'De revolutionibus orbium coelestium' },
  { d: [-1550, -1588], k: 'Mimar Sinan 300\'ü aşkın eser bıraktı', t: 'Süleymaniye Camii 1557\'de bitti. Mimar Sinan\'ın camiler, köprüler, hamamlar ve kervansaraylarla 300\'ü aşkın eser yaptığı biliniyor.', w: 'Mimar Sinan' },
  { d: [-1554, -1570], k: 'İstanbul\'da ilk kahvehane', t: 'Kaynaklara göre İstanbul\'daki ilk kahvehaneler 1554 civarında Tahtakale\'de açıldı. Kısa sürede sohbet ve haber merkezi oldular.', w: 'Turkish coffee' },
  { d: [-1556, -1605], k: 'Okuma yazma bilmeyen kitap sever', t: 'Babür hükümdarı Ekber okuma yazma bilmiyordu ama binlerce ciltlik bir kütüphane kurdu ve kitapları ona yüksek sesle okuturdu.', w: 'Akbar' },
  { d: [-1571, -1572], k: 'Cervantes İnebahtı\'da elini kaybetti', t: 'Don Kişot\'un yazarı Cervantes, 1571\'deki İnebahtı Deniz Savaşı\'nda yaralandı ve sol elini bir daha kullanamadı.', w: 'Miguel de Cervantes' },
  { d: [-1577, -1580], k: 'İstanbul\'un gözlemevi yıkıldı', t: 'Takiyüddin 1577\'de Galata\'da büyük bir gözlemevi kurdu. Gözlemevi yalnızca üç yıl sonra, 1580\'de yıktırıldı.', w: 'Constantinople observatory of Taqi ad-Din' },
  { d: [-1582, -1583], k: '4 Ekim\'in ertesi günü 15 Ekim', t: 'Gregoryen takvimine geçen ülkelerde 1582\'de 4 Ekim\'den sonraki gün 15 Ekim oldu. 10 gün takvimden silindi.', w: 'Gregorian calendar' },
  { d: [-1598, -1629], k: '"İsfahan dünyanın yarısıdır"', t: 'Şah Abbas İsfahan\'ı Safevi başkenti yaptı ve kenti meydan, saray ve camilerle süsledi. İranlılar "İsfahan nısf-ı cihan" (dünyanın yarısı) dedi.', w: 'Isfahan' },
  { d: [-1598, -1681], k: 'Dodo 80 yılda yok oldu', t: 'Mauritius adasındaki dodo kuşunu Avrupalılar 1598\'de gördü. Avlanma ve gemilerle gelen hayvanlar yüzünden 1681\'e varmadan soyu tükendi.', w: 'Dodo' },
  // ---------- 17. yüzyıl ----------
  { d: [-1609, -1615], k: 'Galileo teleskobu gökyüzüne çevirdi', t: 'Galileo 1610\'da Jüpiter\'in dört uydusunu keşfetti. Gökteki her şeyin Dünya\'nın çevresinde dönmediğinin kanıtıydı.', w: 'Galilean moons' },
  { d: [-1610, -1616], k: 'Shakespeare ve Cervantes aynı yıl öldü', t: 'İki büyük yazar 1616\'da, takvimde aynı tarihte (23 Nisan) öldü. Ama İngiltere ile İspanya farklı takvim kullandığı için aslında arada 10 gün vardı.', w: 'World Book Day' },
  { d: [-1630, -1640], k: 'Hezarfen\'in uçuşunun tek tanığı Evliya', t: 'Hezarfen Ahmed Çelebi\'nin Galata Kulesi\'nden Üsküdar\'a uçtuğu anlatılır. Ama bunun tek kaynağı Evliya Çelebi\'dir; doğru olup olmadığı bilinmiyor.', w: 'Hezârfen Ahmed Çelebi' },
  { d: [-1632, -1653], k: 'Tac Mahal\'de 20.000 işçi', t: 'Babür hükümdarı Şah Cihan, eşi Mümtaz Mahal için Tac Mahal\'i yaptırdı. Yapımda yaklaşık 20.000 işçi çalıştı.', w: 'Taj Mahal' },
  { d: [-1633, -1640], k: 'IV. Murad tütüne savaş açtı', t: 'IV. Murad, İstanbul\'da tütün içmeyi ve kahvehaneleri yasakladı; yasağı çiğneyenlerin ağır cezalara çarptırıldığı anlatılır.', w: 'Murad IV' },
  { d: [-1634, -1637], k: 'Bir lale soğanı bir ev fiyatına', t: 'Hollanda\'daki "Lale Çılgınlığı"nda bazı nadir lale soğanları 1637\'de bir ev fiyatına satıldı. Fiyatlar birden çöktü.', w: 'Tulip mania' },
  { d: [-1636, -1640], k: 'Harvard kurulurken IV. Murad tahttaydı', t: 'ABD\'nin en eski üniversitesi Harvard 1636\'da kuruldu. O sırada Osmanlı tahtında IV. Murad vardı.', w: 'Harvard University' },
  { d: [-1639, -1853], k: 'Japonya kapılarını 200 yıl kapattı', t: 'Tokugawa Japonyası 1639\'dan sonra yalnızca Hollandalı ve Çinli tüccarların Nagasaki\'de ticaret yapmasına izin verdi. Kapılar ancak 1853\'te açıldı.', w: 'Sakoku' },
  { d: [-1640, -1682], k: 'Evliya Çelebi\'nin 10 ciltlik gezisi', t: 'Evliya Çelebi yaklaşık 40 yıl Osmanlı topraklarını ve komşularını gezdi; gördüklerini 10 ciltlik Seyahatname\'de anlattı.', w: 'Evliya Çelebi' },
  { d: [-1650, -1660], k: 'Londra\'nın ilk kahvehanesi İzmir bağlantılı', t: 'Londra\'nın ilk kahvehanesini 1652\'de, İzmir\'den dönen bir tüccarın hizmetkârı Pasqua Rosée açtı.', w: 'Pasqua Rosée' },
  { d: [-1666, -1670], k: 'Londra yandı, kayıtlı ölü 6', t: '1666 Büyük Londra Yangını şehrin çoğunu yaktı ama resmî kayıtlarda yalnızca 6 ölüm geçer. Gerçek sayının daha yüksek olduğu düşünülür.', w: 'Great Fire of London' },
  { d: [-1683, -1690], k: 'Newton\'un Principia\'sı ve Viyana', t: 'Osmanlı ordusu 1683\'te Viyana önlerinden çekildikten dört yıl sonra Newton, yerçekimi yasalarını anlatan Principia\'yı yayımladı (1687).', w: 'Philosophiæ Naturalis Principia Mathematica' },
  { d: [-1698, -1705], k: 'Çar Petro sakal vergisi koydu', t: 'Rus çarı Büyük Petro, sakalı moda dışı saydı ve sakal bırakanlardan vergi aldı. Vergiyi ödeyenler yanında bir sakal jetonu taşırdı.', w: 'Beard tax' },
  // ---------- 18. yüzyıl ----------
  { d: [-1717, -1725], k: 'Çiçek aşısı İstanbul\'dan İngiltere\'ye', t: 'İngiliz elçisinin eşi Lady Mary Montagu, İstanbul\'da çiçek hastalığına karşı aşılamayı gördü ve 1721\'de İngiltere\'de tanıttı.', w: 'Lady Mary Wortley Montagu' },
  { d: [-1718, -1730], k: 'Lale Devri', t: 'Osmanlı\'da 1718–1730 arası Lale Devri diye anılır: bahçeler, köşkler, şenlikler ve lale tutkusu. Patrona Halil İsyanı ile sona erdi.', w: 'Tulip period' },
  { d: [-1727, -1745], k: 'Gutenberg\'den 280 yıl sonra ilk Türkçe matbaa', t: 'İbrahim Müteferrika, Arap harfli Türkçe kitaplar basan ilk matbaayı 1727\'de kurdu. Gutenberg\'in matbaasından yaklaşık 280 yıl sonraydı.', w: 'İbrahim Müteferrika' },
  { d: [-1752, -1753], k: 'Franklin\'in uçurtması', t: 'Benjamin Franklin 1752\'de fırtınada uçurtma deneyiyle yıldırımın elektrik olduğunu göstermeye çalıştı ve paratoneri icat etti.', w: 'Kite experiment' },
  { d: [-1755, -1760], k: 'Lizbon depremi Avrupa\'yı sarstı', t: '1 Kasım 1755\'teki Lizbon depremi, ardından gelen tsunami ve yangın şehri büyük ölçüde yok etti. Filozoflar yıllarca bu felaketi tartıştı.', w: '1755 Lisbon earthquake' },
  { d: [-1770, -1780], k: 'Mozart 20 yaşındayken ABD kuruldu', t: 'Bağımsızlık Bildirgesi 1776\'da imzalandığında Mozart 20 yaşındaydı ve Salzburg\'da beste yapıyordu.', w: 'Wolfgang Amadeus Mozart' },
  { d: [-1774, -1783], k: 'ABD kurulurken I. Abdülhamid tahttaydı', t: 'ABD bağımsızlığını 1776\'da ilan ettiğinde Osmanlı tahtında I. Abdülhamid vardı. ABD, Osmanlı\'dan çok daha genç bir devlettir.', w: 'Abdul Hamid I' },
  { d: [-1783, -1784], k: 'İlk balon yolcuları: koyun, ördek, horoz', t: 'Montgolfier kardeşlerin sıcak hava balonuyla 1783\'te ilk uçan canlılar bir koyun, bir ördek ve bir horozdu. İnsanlar iki ay sonra uçtu.', w: 'Montgolfier brothers' },
  { d: [-1793, -1795], k: 'Fransa günü 10 saate böldü', t: 'Fransız Devrimi metre ve kiloyu getirdi. Bir süre günü de 10 saate, saati 100 dakikaya bölen ondalık saat kullanıldı ama tutmadı.', w: 'Decimal time' },
  { d: [-1799, -1815], k: 'Napolyon kısa değildi', t: 'Napolyon\'un boyu yaklaşık 1,69 m\'ydi; döneminin Fransız erkeklerinin ortalamasına yakın. "Kısa Napolyon" efsanesi İngiliz karikatürlerinden ve ölçü birimi karışıklığından doğdu.', w: 'Napoleon complex' },
  // ---------- 19. yüzyıl ----------
  { d: [-1804, -1806], k: 'Köle isyanından doğan devlet', t: 'Haiti 1804\'te bağımsız oldu: köleleştirilmiş insanların başarılı bir isyanla kurduğu ilk devlet.', w: 'Haitian Revolution' },
  { d: [-1809, -1815], k: 'Darwin ve Lincoln aynı gün doğdu', t: 'Charles Darwin ve Abraham Lincoln, ikisi de 12 Şubat 1809\'da doğdu.', w: 'Charles Darwin' },
  { d: [-1815, -1817], k: 'Yazsız yıl ve Frankenstein', t: '1815\'te Endonezya\'da Tambora yanardağı patladı. 1816 "yazsız yıl" oldu; evde kalan Mary Shelley Cenevre Gölü kıyısında Frankenstein\'ı yazmaya başladı.', w: 'Year Without a Summer' },
  { d: [-1824, -1827], k: 'Beethoven 9. Senfoni\'yi duyamadı', t: 'Beethoven 9. Senfoni\'yi 1824\'te sahneye koyduğunda neredeyse tamamen sağırdı. Anlatılana göre alkışları görebilmesi için onu seyirciye doğru çevirdiler.', w: 'Symphony No. 9 (Beethoven)' },
  { d: [-1826, -1828], k: 'Yeniçeri Ocağı kapandı', t: 'II. Mahmud 1826\'da Yeniçeri Ocağı\'nı kaldırdı. Osmanlı tarihinde bu olay "Vaka-i Hayriye" (hayırlı olay) diye anılır.', w: 'Auspicious Incident' },
  { d: [-1826, -1828], k: 'İlk fotoğraf saatlerce poz istedi', t: 'Niépce\'nin pencereden çektiği, günümüze ulaşan en eski fotoğraf 1826–27\'den. Görüntünün oluşması için saatlerce poz gerekti.', w: 'View from the Window at Le Gras' },
  { d: [-1829, -1833], k: 'Büyük Dalga', t: 'Hokusai\'nin "Kanagawa\'da Büyük Dalga" baskısı 1831 civarında yapıldı. Dünyanın en çok tanınan Japon sanat eseridir.', w: 'The Great Wave off Kanagawa' },
  { d: [-1830, -1831], k: 'Tren açılış gününde bir bakanı ezdi', t: 'Liverpool–Manchester demiryolunun açılışında, 1830\'da milletvekili William Huskisson lokomotifin altında kaldı. Geniş yankı bulan ilk demiryolu kazasıydı.', w: 'William Huskisson' },
  { d: [-1831, -1836], k: 'Darwin\'in beş yıllık gemi yolculuğu', t: 'Darwin, Beagle gemisiyle 1831–1836 arasında dünyayı dolaştı. Galapagos\'ta gördüğü canlılar evrim fikrinin tohumlarını attı.', w: 'Second voyage of HMS Beagle' },
  { d: [-1839, -1842], k: 'Tanzimat ve fotoğraf aynı yıl', t: 'Tanzimat Fermanı 1839\'da okundu. Aynı yıl Paris\'te Daguerre\'in fotoğraf makinesi dünyaya tanıtıldı.', w: 'Daguerreotype' },
  { d: [-1842, -1852], k: 'İlk bilgisayar programını bir kadın yazdı', t: 'Ada Lovelace 1843\'te henüz yapılmamış bir hesap makinesi için algoritma yazdı. İlk bilgisayar programı sayılır.', w: 'Ada Lovelace' },
  { d: [-1843, -1850], k: 'Faks, telefondan eski', t: 'Faks makinesinin atası sayılan cihazın patenti 1843\'te alındı: telefonun icadından 33 yıl önce.', w: 'Fax' },
  { d: [-1844, -1846], k: 'İlk telgraf: "Tanrı neler yarattı"', t: 'Samuel Morse 1844\'te Washington\'dan Baltimore\'a ilk resmî telgraf mesajını gönderdi: "What hath God wrought" (Tanrı neler yarattı).', w: 'Electrical telegraph' },
  { d: [-1845, -1849], k: 'Osmanlı\'dan İrlanda\'ya yardım', t: 'Büyük İrlanda Kıtlığı\'nda Sultan Abdülmecid\'in İrlanda\'ya para ve erzak yardımı gönderdiği anlatılır; yardımın miktarı ve gemiler tartışmalıdır.', w: 'Great Famine (Ireland)' },
  { d: [-1846, -1850], k: 'Ameliyatlar uyanıkken yapılırdı', t: 'Eterle ilk halka açık narkozlu ameliyat 1846\'da Boston\'da yapıldı. Ondan önce hastalar ameliyatları uyanık geçirirdi.', w: 'Ether Day' },
  { d: [-1854, -1856], k: 'Florence Nightingale Üsküdar\'da', t: 'Modern hemşireliğin kurucusu Florence Nightingale, Kırım Savaşı\'nda Üsküdar\'daki Selimiye Kışlası\'nda yaralılara baktı.', w: 'Florence Nightingale' },
  { d: [-1854, -1856], k: 'İlk Osmanlı telgrafı savaşla geldi', t: 'Osmanlı\'nın ilk telgraf hatları Kırım Savaşı sırasında, 1855\'te kuruldu. İstanbul\'dan cepheye haber artık saatler içinde gidiyordu.', w: 'Crimean War' },
  { d: [-1867, -1868], k: 'Alaska dönümü 2 sente satıldı', t: 'Rusya 1867\'de Alaska\'yı ABD\'ye 7,2 milyon dolara sattı: dönümü yaklaşık 2 sent.', w: 'Alaska Purchase' },
  { d: [-1868, -1877], k: 'Samuraylar kılıçlarını bıraktı', t: 'Meiji Japonyası hızla modernleşti; 1876\'da sokakta kılıç taşımak yasaklandı ve samuray sınıfı ayrıcalıklarını yitirdi.', w: 'Haitōrei Edict' },
  { d: [-1869, -1871], k: 'Mendeleyev boşlukları tahmin etti', t: 'Mendeleyev 1869\'da periyodik tabloyu yayımladı ve henüz bulunmamış elementler için boşluklar bıraktı. Galyum ve germanyum sonradan tam tahmin ettiği gibi bulundu.', w: 'Dmitri Mendeleev' },
  { d: [-1875, -1880], k: 'Tünel: dünyanın ikinci metrosu', t: 'Karaköy ile Beyoğlu arasındaki Tünel 1875\'te açıldı. Londra metrosundan sonra dünyanın hâlâ çalışan en eski ikinci yeraltı raylı sistemidir.', w: 'Tünel' },
  { d: [-1876, -1877], k: 'Telefon ve II. Abdülhamid aynı yıl', t: 'Graham Bell telefonun patentini 1876 Mart\'ında aldı; aynı yılın Ağustos\'unda II. Abdülhamid tahta çıktı.', w: 'Invention of the telephone' },
  { d: [-1883, -1890], k: 'Orient Express İstanbul\'a geldi', t: 'Orient Express 1883\'te Paris\'ten yola çıktı; yolculuğun son kısmı Varna\'dan vapurla yapılıyordu. 1889\'dan sonra tren doğrudan İstanbul\'a girdi.', w: 'Orient Express' },
  { d: [-1883, -1884], k: 'Krakatoa 4.800 km öteden duyuldu', t: '1883\'te Krakatoa yanardağının patlaması 4.800 km uzaktaki Rodrigues Adası\'ndan duyuldu. Kayıtlara geçen en yüksek seslerden biridir.', w: '1883 eruption of Krakatoa' },
  { d: [-1886, -1905], k: 'Özgürlük Heykeli başta yeşil değildi', t: 'Özgürlük Heykeli 1886\'da açıldığında parlak bakır rengindeydi. Bakır havayla tepkimeye girdikçe yıllar içinde yeşile döndü.', w: 'Statue of Liberty' },
  { d: [-1887, -1910], k: 'Eyfel Kulesi 20 yıl sonra sökülecekti', t: 'Eyfel Kulesi 1889 Dünya Fuarı için yapıldı ve 20 yıl sonra sökülmesi planlanıyordu. Radyo anteni olarak işe yarayınca kurtuldu.', w: 'Eiffel Tower' },
  { d: [-1889, -1895], k: 'Nintendo, Osmanlı zamanında kuruldu', t: 'Nintendo 1889\'da Kyoto\'da oyun kartı üreticisi olarak kuruldu. O sırada Osmanlı tahtında II. Abdülhamid vardı.', w: 'Nintendo' },
  { d: [-1889, -1892], k: 'Chaplin ile Hitler 4 gün arayla doğdu', t: 'Charlie Chaplin 16 Nisan 1889\'da, Adolf Hitler 20 Nisan 1889\'da doğdu. Chaplin yıllar sonra "Büyük Diktatör"de onunla alay etti.', w: 'The Great Dictator' },
  { d: [-1895, -1897], k: 'Sinema ve Yıldız Sarayı', t: 'Lumière kardeşler ilk halka açık film gösterimini 1895\'te Paris\'te yaptı. Kısa süre sonra, 1896\'da İstanbul\'da da ilk gösterimler yapıldı.', w: 'Auguste and Louis Lumière' },
  { d: [-1896, -1897], k: 'Tarihin en kısa savaşı 38 dakika', t: '1896\'daki İngiltere–Zanzibar Savaşı yaklaşık 38 ile 45 dakika arasında sürdü. Bilinen en kısa savaştır.', w: 'Anglo-Zanzibar War' },
  { d: [-1896, -1897], k: 'Modern Olimpiyatlar Atina\'da başladı', t: 'İlk modern Olimpiyat Oyunları 1896\'da Atina\'da yapıldı. Kadınlar yarışamadı; ilk kez 1900\'de katıldılar.', w: '1896 Summer Olympics' },
  // ---------- 20. yüzyıl ----------
  { d: [-1900, -1908], k: 'Hicaz Demiryolu bağışlarla yapıldı', t: 'Şam\'dan Medine\'ye uzanan Hicaz Demiryolu 1900–1908 arasında, büyük ölçüde İslam dünyasından toplanan bağışlarla yapıldı.', w: 'Hejaz railway' },
  { d: [-1903, -1908], k: 'İlk uçuş bir yolcu uçağının kanadından kısa', t: 'Wright kardeşlerin 1903\'teki ilk uçuşu 12 saniye sürdü ve 37 metre gitti. Bu, bir Boeing 747\'nin kanat açıklığından kısadır.', w: 'Wright Flyer' },
  { d: [-1903, -1911], k: 'İki ayrı bilimde Nobel alan tek kişi', t: 'Marie Curie 1903\'te fizik, 1911\'de kimya Nobel\'i aldı. İki farklı bilim dalında Nobel kazanan tek kişidir.', w: 'Marie Curie' },
  { d: [-1905, -1906], k: 'Einstein\'ın mucize yılı', t: 'Einstein 1905\'te, patent ofisinde memurken dört çığır açan makale yayımladı; E=mc² bunlardan biridir.', w: 'Annus mirabilis papers' },
  { d: [-1908, -1927], k: 'Model T: 15 milyon otomobil', t: 'Ford Model T 1908–1927 arasında 15 milyondan fazla üretildi. Henry Ford\'a göre müşteri "siyah olduğu sürece" istediği rengi seçebilirdi.', w: 'Ford Model T' },
  { d: [-1910, -1911], k: 'Kuyruklu yıldız hapı satıldı', t: '1910\'da Dünya, Halley kuyruklu yıldızının kuyruğundan geçti. Zehirli gaz korkusuyla bazı yerlerde "kuyruklu yıldız hapı" satıldı.', w: 'Halley\'s Comet' },
  { d: [-1911, -1912], k: 'Amundsen Güney Kutbu\'na 34 gün önce vardı', t: 'Norveçli Amundsen Aralık 1911\'de Güney Kutbu\'na ulaştı. İngiliz Scott 34 gün sonra vardığında orada Norveç bayrağını buldu.', w: 'Amundsen\'s South Pole expedition' },
  { d: [-1910, -1914], k: 'Oreo, Titanik\'ten bir ay önce çıktı', t: 'Oreo bisküvisi Mart 1912\'de satışa çıktı. Titanik ise bir ay sonra, Nisan 1912\'de battı.', w: 'Oreo' },
  { d: [-1914, -1915], k: 'Siperlerde Noel ateşkesi', t: '1914 Noeli\'nde Batı Cephesi\'nde bazı İngiliz ve Alman askerleri kendiliğinden ateşkes yaptı; şarkı söylediler, hediyeleştiler.', w: 'Christmas truce' },
  { d: [-1917, -1918], k: 'Ekim Devrimi Kasım\'da oldu', t: 'Rusya o sırada eski Jülyen takvimini kullanıyordu. Bu yüzden "Ekim Devrimi" bugünkü takvimle 7 Kasım 1917\'de oldu.', w: 'October Revolution' },
  { d: [-1918, -1920], k: 'İspanyol gribi dünyanın üçte birine bulaştı', t: '1918 grip salgını yaklaşık 500 milyon kişiye, yani dünya nüfusunun üçte birine bulaştı.', w: 'Spanish flu' },
  { d: [-1922, -1923], k: 'Saltanat kalktı, Tutankamon bulundu', t: 'Saltanat 1 Kasım 1922\'de kaldırıldı. Üç gün sonra, 4 Kasım\'da Howard Carter Mısır\'da Tutankamon\'un mezarının ilk basamağını buldu.', w: 'Discovery of the tomb of Tutankhamun' },
  { d: [-1925, -1926], k: 'Türkiye takvimini ve saatini değiştirdi', t: '1 Ocak 1926\'dan itibaren Türkiye Hicri ve Rumi takvimleri bırakıp Gregoryen takvime ve uluslararası saate geçti.', w: 'Rumi calendar' },
  { d: [-1926, -1928], k: 'İlk televizyon gösterimi', t: 'John Logie Baird 1926\'da Londra\'da hareketli görüntüyü aktaran televizyonunu ilk kez halka gösterdi.', w: 'John Logie Baird' },
  { d: [-1928, -1929], k: 'Harf Devrimi', t: 'Türkiye 1928\'de Latin harflerine geçti. Atatürk yurdu gezip kara tahta başında yeni harfleri kendisi öğretti.', w: 'Turkish alphabet' },
  { d: [-1928, -1932], k: 'Penisilin bir tatil dönüşü bulundu', t: 'Alexander Fleming 1928\'de tatilden döndüğünde unuttuğu bir bakteri kabında küf mantarının bakterileri öldürdüğünü gördü.', w: 'Penicillin' },
  { d: [-1930, -1932], k: 'Plüton 76 yıl gezegen kaldı', t: 'Plüton 1930\'da keşfedildi ve 2006\'da gezegen sayılmaktan çıkarıldı. Bu sürede Güneş\'in çevresinde bir turunu bile tamamlayamadı.', w: 'Pluto' },
  { d: [-1930, -1945], k: 'Türk kadınları Fransızlardan önce oy verdi', t: 'Türkiye\'de kadınlar 1934\'te milletvekili seçme ve seçilme hakkı kazandı. Fransa\'da bu hak 1944\'te, İsviçre\'de ancak 1971\'de geldi.', w: 'Women\'s suffrage' },
  { d: [-1934, -1936], k: 'Soyadı Kanunu', t: '1934\'teki Soyadı Kanunu\'na kadar Türkiye\'de çoğu kişinin resmî bir soyadı yoktu; insanlar lakap, baba adı ya da memleketle anılıyordu.', w: 'Surname Law (Turkey)' },
  { d: [-1936, -1937], k: 'Olimpiyat meşalesi 1936\'da doğdu', t: 'Olimpiya\'dan stadyuma uzanan meşale koşusu ilk kez 1936 Berlin Olimpiyatları\'nda yapıldı.', w: 'Olympic flame' },
  { d: [-1936, -1938], k: 'İlk kadın savaş pilotu', t: 'Sabiha Gökçen 1937\'de savaş uçağı kullanan ilk kadın pilotlardan biri oldu.', w: 'Sabiha Gökçen' },
  { d: [-1945, -1947], k: 'İlk bilgisayar 30 ton', t: 'ENIAC 1945\'te çalışmaya başladı: yaklaşık 30 ton ağırlığındaydı ve bir odayı dolduruyordu.', w: 'ENIAC' },
  { d: [-1957, -1958], k: 'Uzaydaki ilk canlı bir sokak köpeği', t: 'Sovyetler Ekim 1957\'de Sputnik\'i fırlattı. Bir ay sonra Moskova sokaklarında bulunan köpek Layka, yörüngeye çıkan ilk canlı oldu.', w: 'Laika' },
  { d: [-1961, -1962], k: 'Gagarin\'in uçuşu 108 dakika', t: 'Yuri Gagarin 1961\'de Dünya\'nın çevresini bir kez dolaştı. Bütün uçuş 108 dakika sürdü.', w: 'Vostok 1' },
  { d: [-1969, -1970], k: 'İnternetin ilk mesajı: "LO"', t: '1969\'da ARPANET üzerinden ilk mesaj gönderilirken "LOGIN" yazılacaktı; sistem iki harften sonra çöktü ve yalnızca "LO" gitti.', w: 'ARPANET' },
  { d: [-1969, -1972], k: 'Ay\'a giden bilgisayarın 4 KB belleği', t: 'Apollo rehber bilgisayarının değiştirilebilir belleği yaklaşık 4 kilobayttı. Bugünkü bir telefonun milyonda birinden de az.', w: 'Apollo Guidance Computer' },
  { d: [-1970, -1975], k: 'Savaşı 1974\'e kadar süren asker', t: 'Japon subay Hiroo Onoda, savaşın bittiğine inanmadığı için Filipinler ormanında 1974\'e kadar saklandı. Eski komutanı gelip emir verince teslim oldu.', w: 'Hiroo Onoda' },
  { d: [-1973, -1975], k: 'İlk cep telefonu görüşmesi', t: 'Motorola mühendisi Martin Cooper 1973\'te New York sokağında ilk cep telefonu görüşmesini yaptı. Telefon yaklaşık 1 kiloydu.', w: 'Martin Cooper (inventor)' },
  { d: [-1973, -1974], k: 'Boğaz Köprüsü Cumhuriyetin 50. yılında', t: 'Boğaziçi Köprüsü, Cumhuriyetin 50. yıl dönümünde, 30 Ekim 1973\'te açıldı. Avrupa ile Asya\'yı birleştiren ilk köprüydü.', w: 'Bosphorus Bridge' },
  { d: [-1975, -1980], k: 'Star Wars ve giyotin aynı yıl', t: 'Fransa\'da giyotinle son idam Eylül 1977\'de yapıldı. Aynı yılın Mayıs\'ında Star Wars sinemalarda gösterime girmişti.', w: 'Hamida Djandoubi' },
  { d: [-1977, -1982], k: 'Çiçek hastalığı yok edildi', t: 'Dünya Sağlık Örgütü 1980\'de çiçek hastalığının yeryüzünden silindiğini ilan etti. İnsanlığın tamamen yok ettiği ilk hastalıktır.', w: 'Smallpox' },
  { d: [-1989, -1991], k: 'Berlin Duvarı ve Web aynı yıl', t: 'Tim Berners-Lee, World Wide Web önerisini Mart 1989\'da yazdı. Berlin Duvarı aynı yılın Kasım\'ında yıkıldı.', w: 'History of the World Wide Web' },
  { d: [-1991, -1993], k: 'İlk web sitesi hâlâ açık', t: 'Dünyanın ilk web sitesi 1991\'de CERN\'de yayına girdi. Yeniden kurulan kopyası bugün de info.cern.ch adresinde açılıyor.', w: 'Info.cern.ch' },
  { d: [-1993, -1995], k: 'Türkiye internete 1993\'te bağlandı', t: 'Türkiye\'nin ilk internet bağlantısı 12 Nisan 1993\'te ODTÜ\'den kuruldu.', w: 'Internet in Turkey' },
  { d: [-1997, -1998], k: 'Bilgisayar dünya satranç şampiyonunu yendi', t: 'IBM\'in Deep Blue bilgisayarı 1997\'de Garry Kasparov\'u bir maç boyunca yendi.', w: 'Deep Blue versus Garry Kasparov' },
  { d: [-2005, -2007], k: 'YouTube\'un ilk videosu 19 saniye', t: 'YouTube\'a yüklenen ilk video "Me at the zoo", 2005\'te yüklendi ve 19 saniye sürüyor: kurucu ortaklardan biri hayvanat bahçesinde fillerin önünde.', w: 'Me at the zoo' },
  { d: [-1953, -1954], k: 'Everest\'in zirvesine ilk çıkış', t: 'Edmund Hillary ve Tenzing Norgay 29 Mayıs 1953\'te Everest\'in zirvesine çıkan ilk insanlar oldu. Zirvede yalnızca 15 dakika kaldılar.', w: '1953 British Mount Everest expedition' },
  { d: [-1968, -1969], k: 'TRT televizyonu haftada üç gün', t: 'Türkiye\'de düzenli televizyon yayınını TRT 1968\'de Ankara\'da başlattı. İlk zamanlarda yayın haftada yalnızca üç gün, birkaç saat sürüyordu.', w: 'TRT 1' },
  { d: [-2004, -2006], k: 'Facebook bir yurt odasında doğdu', t: 'Facebook 2004\'te Harvard\'daki bir öğrenci yurdunda, başlangıçta yalnızca Harvard öğrencileri için kuruldu.', w: 'Facebook' },
  { d: [-2007, -2009], k: 'İlk iPhone\'da uygulama mağazası yoktu', t: 'İlk iPhone 2007\'de çıktı ama telefona uygulama indirilemiyordu. App Store bir yıl sonra, 2008\'de açıldı.', w: 'IPhone (1st generation)' },
  { d: [-2012, -2014], k: 'Mars\'ta kendine "mutlu yıllar" çalan robot', t: 'NASA\'nın Curiosity robotu 2012\'de Mars\'a indi. İnişinin birinci yıl dönümünde, 2013\'te, Mars\'ta "İyi ki doğdun" şarkısını çaldı.', w: 'Curiosity (rover)' },
  { d: [-2016, -2017], k: 'Yapay zekâ Go\'da insanı yendi', t: 'Google DeepMind\'ın AlphaGo programı 2016\'da dünyanın en iyi Go oyuncularından Lee Sedol\'u 4-1 yendi. Go, satrançtan çok daha karmaşık sayılır.', w: 'AlphaGo versus Lee Sedol' },
  { d: [-2020, -2021], k: 'İnsan yapımı şeyler canlıları geçti', t: '2020\'de yayımlanan bir araştırmaya göre beton, metal, plastik gibi insan yapımı nesnelerin toplam kütlesi, Dünya\'daki bütün canlıların kütlesini geçti.', w: 'Technosphere' },
  { d: [-2022, -2023], k: 'James Webb\'in ilk renkli fotoğrafları', t: 'James Webb Uzay Teleskobu 2022\'de ilk görüntülerini yayımladı. Bir kum tanesi büyüklüğündeki gökyüzü parçasında binlerce galaksi görünüyordu.', w: 'James Webb Space Telescope' },
  { d: [-2019, -2020], k: 'Bir kara deliğin ilk fotoğrafı', t: '2019\'da gökbilimciler M87 galaksisindeki kara deliğin ilk görüntüsünü yayımladı. Görüntü dünyanın dört bir yanındaki teleskopların birleştirilmesiyle elde edildi.', w: 'Event Horizon Telescope' }
];
